SELECT 'gongkao', '类比推理总览', 'kp-xc-analogy-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"类比推理总览"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心方法论：","marks":[{"type":"bold"}]},{"type":"text","text":"类比推理的本质是「找词语之间的关系」。解题步骤：先横向找题干关系，再纵向比较选项。先整体再局部，先横向再纵向。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、知识体系"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"外延关系（约 42%）：全同、并列、交叉、包容、全异"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"内涵关系（约 57%）：对应关系（功能/场所/原材料/因果等）、条件、属性"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"语义关系（约 15%）：近义、反义、比喻义、象征义"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"语法关系（约 6%）：主谓、动宾、主宾、偏正、构词"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、解题三步法"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"第一步：看题干 — 判断词语之间是什么关系（造句法辅助）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"第二步：看选项 — 找和题干关系一致的选项"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"第三步：纵向比较 — 如果多个选项都符合，再纵向比较细节"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、造句法"}]},{"type":"paragraph","content":[{"type":"text","text":"用两个词语造一个简单句子，看关系："}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「A 是 B 的一种」→ 种属/包容关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「A 是 B 的一部分」→ 组成关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「A 和 B 都是 X」→ 并列关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「A 和 B 有交叉」→ 交叉关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「用 A 来 B」→ 动宾/功能对应"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"先整体再局部 — 不要先看词语内部结构"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"先横向再纵向 — 先看题干关系，再纵向比较选项"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"位置必须对应 — 题干是「小:大」，选项不能选「大:小」"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"类比推理共 10 道题，建议每天练习 10 道。重点训练「造句法」的速度，目标每题 20 秒内完成。"}]}]}]}]}$$ AS jsonb), NULL, '类比推理模块总览：知识体系、解题三步法、造句法。', category_node.id, CAST('["类比推理", "总览", "造句法"]' AS jsonb), TRUE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_logic_analogy_reasoning", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
